'use client';

import { useEffect, useRef } from 'react';

// A slowly turning Earth drawn in monospace characters, with a marker on Lima.
// Orthographic projection of a land bitmask (src/data/globe-land.ts, generated by
// src/design/globe/export_land.py). The sphere's geometry is precomputed per cell,
// so a frame only shifts the longitude and looks the land up. Canvas 2D, glyphs
// blitted from a small atlas. Pauses off-screen; static under reduced motion.

const CW = 7;            // cell width, CSS px
const CH = 12;           // cell height, CSS px
const FONT_PX = 11;
const FONT = `${FONT_PX}px ui-monospace, SFMono-Regular, Menlo, monospace`;
const SS = 2;            // samples per cell side
const TILT = (-8 * Math.PI) / 180;        // view centre latitude
const START_LON = -40;                    // degrees: Lima enters from the left and crosses the face
const SPIN_DEG_PER_S = 3;                 // one turn every 2 minutes
const LIMA = { lat: -12.0464, lon: -77.0428 };
const LIGHT = (() => {
    const v = [-0.55, 0.45, 0.7];
    const n = Math.hypot(v[0], v[1], v[2]);
    return v.map((x) => x / n);
})();
const LAND_RAMP = ' .:-=+*#%';
const GLYPHS = ' .:-=+*#%·';
const GREY = '#e5e5e5';
const DIM = '#a3a3a3';
const BLUE = '#60a5fa';

interface AsciiGlobeProps {
    revealed?: boolean;
    remoteLabel?: string;
    className?: string;
}

export function AsciiGlobe({ revealed = true, remoteLabel = 'REMOTE', className = '' }: AsciiGlobeProps) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const revealedRef = useRef(revealed);
    const remoteRef = useRef(remoteLabel);
    const startRevealRef = useRef<(() => void) | null>(null);

    useEffect(() => {
        remoteRef.current = remoteLabel;
    }, [remoteLabel]);

    useEffect(() => {
        revealedRef.current = revealed;
        if (revealed) startRevealRef.current?.();
    }, [revealed]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        let disposed = false;
        let land: Uint8Array | null = null;
        let landW = 0, landH = 0;

        let width = 0, height = 0, dpr = 1;
        let R = 0, cx = 0, cy = 0, cols = 0, rows = 0, gx0 = 0, gy0 = 0;
        // Per cell
        let inside = new Uint8Array(0);     // samples inside the disc
        let shade = new Float32Array(0);    // mean lambert term
        let latGrat = new Uint8Array(0);    // near a 30° parallel
        // Per sample
        let sLatRow = new Int32Array(0);    // land-row index for the sample's latitude
        let sDLon = new Float32Array(0);    // longitude relative to the view centre, degrees
        let atlas: HTMLCanvasElement | null = null;

        let lon0 = START_LON;
        let raf: number | null = null;
        let last = 0;
        let reveal = reduced ? 1 : 0;   // 0..1 scan-in progress
        let revealStart = -1;

        const buildAtlas = () => {
            const a = document.createElement('canvas');
            a.width = Math.ceil(GLYPHS.length * CW * dpr);
            a.height = Math.ceil(CH * dpr);
            const g = a.getContext('2d')!;
            g.scale(dpr, dpr);
            g.font = FONT;
            g.textBaseline = 'top';
            g.fillStyle = GREY;
            for (let i = 0; i < GLYPHS.length; i++) g.fillText(GLYPHS[i], i * CW, 0);
            atlas = a;
        };

        const layout = () => {
            const rect = canvas.getBoundingClientRect();
            width = rect.width;
            height = rect.height;
            dpr = Math.min(window.devicePixelRatio || 1, 2);
            canvas.width = Math.round(width * dpr);
            canvas.height = Math.round(height * dpr);

            R = Math.max(40, Math.min(height / 2 - 6, width * 0.42));
            cx = width - R - 12;
            cy = height / 2;
            cols = Math.ceil((2 * R) / CW) + 2;
            rows = Math.ceil((2 * R) / CH) + 2;
            gx0 = cx - (cols * CW) / 2;
            gy0 = cy - (rows * CH) / 2;

            const n = cols * rows;
            inside = new Uint8Array(n);
            shade = new Float32Array(n);
            latGrat = new Uint8Array(n);
            sLatRow = new Int32Array(n * SS * SS).fill(-1);
            sDLon = new Float32Array(n * SS * SS);
            const sinT = Math.sin(TILT), cosT = Math.cos(TILT);

            for (let r = 0; r < rows; r++) {
                for (let c = 0; c < cols; c++) {
                    const ci = r * cols + c;
                    let ins = 0, sh = 0, grat = 0;
                    for (let sy = 0; sy < SS; sy++) {
                        for (let sx = 0; sx < SS; sx++) {
                            const px = gx0 + (c + (sx + 0.5) / SS) * CW;
                            const py = gy0 + (r + (sy + 0.5) / SS) * CH;
                            const x = (px - cx) / R, y = -(py - cy) / R;
                            const rho2 = x * x + y * y;
                            if (rho2 > 1) continue;
                            ins++;
                            const z = Math.sqrt(1 - rho2);
                            sh += Math.max(0, x * LIGHT[0] + y * LIGHT[1] + z * LIGHT[2]);
                            const rho = Math.sqrt(rho2);
                            const cc = Math.asin(Math.min(1, rho));
                            let lat: number, dlon: number;
                            if (rho < 1e-9) {
                                lat = TILT; dlon = 0;
                            } else {
                                lat = Math.asin(Math.cos(cc) * sinT + (y * Math.sin(cc) * cosT) / rho);
                                dlon = Math.atan2(x * Math.sin(cc), rho * cosT * Math.cos(cc) - y * sinT * Math.sin(cc));
                            }
                            const latDeg = (lat * 180) / Math.PI;
                            const si = ci * SS * SS + sy * SS + sx;
                            sDLon[si] = (dlon * 180) / Math.PI;
                            sLatRow[si] = Math.min(landH - 1, Math.max(0, Math.floor(((90 - latDeg) / 180) * landH)));
                            if (Math.abs(latDeg - Math.round(latDeg / 30) * 30) < 0.6) grat++;
                        }
                    }
                    inside[ci] = ins;
                    shade[ci] = ins ? sh / ins : 0;
                    latGrat[ci] = grat;
                }
            }
            buildAtlas();
        };

        const isLand = (row: number, lonDeg: number) => {
            let col = Math.floor(((lonDeg + 180) / 360) * landW) % landW;
            if (col < 0) col += landW;
            const i = row * landW + col;
            return (land![i >> 3] & (0x80 >> (i & 7))) !== 0;
        };

        const blit = (glyph: number, x: number, y: number, alpha: number) => {
            ctx.globalAlpha = alpha;
            ctx.drawImage(atlas!, glyph * CW * dpr, 0, CW * dpr, CH * dpr, x, y, CW, CH);
        };

        const draw = (now: number) => {
            if (!land || !atlas) return;
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            ctx.clearRect(0, 0, width, height);

            // Lima on screen (forward orthographic)
            const latL = (LIMA.lat * Math.PI) / 180;
            const dl = ((LIMA.lon - lon0) * Math.PI) / 180;
            const sinT = Math.sin(TILT), cosT = Math.cos(TILT);
            const cosc = sinT * Math.sin(latL) + cosT * Math.cos(latL) * Math.cos(dl);
            const mxRaw = cx + R * Math.cos(latL) * Math.sin(dl);
            const myRaw = cy - R * (cosT * Math.sin(latL) - sinT * Math.cos(latL) * Math.cos(dl));
            const mc = Math.round((mxRaw - gx0) / CW);
            const mr = Math.round((myRaw - gy0) / CH);
            const markerVis = Math.min(1, Math.max(0, (cosc - 0.1) / 0.25));

            const revealRow = reveal * (rows + 6);
            const sps = SS * SS;
            for (let r = 0; r < rows; r++) {
                if (r > revealRow) break;
                const scan = reveal < 1 ? Math.max(0, 1 - (revealRow - r) / 6) : 0;
                for (let c = 0; c < cols; c++) {
                    const ci = r * cols + c;
                    const ins = inside[ci];
                    if (!ins) continue;
                    if (markerVis > 0 && r === mr && c >= mc - 1 && c <= mc + 1) continue;
                    let hits = 0, lonGrat = 0;
                    const base = ci * sps;
                    for (let s = 0; s < sps; s++) {
                        const row = sLatRow[base + s];
                        if (row < 0) continue;
                        const lon = sDLon[base + s] + lon0;
                        if (isLand(row, lon)) hits++;
                        const wrapped = ((lon % 30) + 30) % 30;
                        if (wrapped < 0.6 || wrapped > 29.4) lonGrat++;
                    }
                    const sh = shade[ci];
                    const lf = hits / ins;
                    const x = gx0 + c * CW, y = gy0 + r * CH;
                    let glyph: number, alpha: number;
                    if (lf > 0.15) {
                        const lvl = sh * (0.55 + 0.45 * lf);
                        glyph = GLYPHS.indexOf(LAND_RAMP[Math.max(2, Math.min(8, 2 + Math.floor(lvl * 7)))]);
                        alpha = 0.18 + 0.72 * lvl;
                    } else if (ins < sps) {
                        glyph = 9; alpha = 0.45;                          // rim
                    } else if (latGrat[ci] || lonGrat) {
                        glyph = 9; alpha = 0.08 + 0.18 * sh;              // graticule
                    } else if ((r + c) % 2 === 0) {
                        glyph = 1; alpha = 0.05 + 0.22 * sh;              // ocean
                    } else {
                        continue;
                    }
                    if (scan) {
                        alpha = Math.min(1, alpha + scan * 0.6);
                        if (glyph === 0 || glyph === 1) glyph = 3;
                    }
                    blit(glyph, x, y, alpha);
                }
            }

            if (reveal < 1 || markerVis <= 0) {
                ctx.globalAlpha = 1;
                return;
            }

            // Marker
            const sx = gx0 + mc * CW, sy = gy0 + mr * CH;
            const pulse = reduced ? 1 : 0.65 + 0.35 * Math.sin(now / 320);
            ctx.font = FONT;
            ctx.textBaseline = 'top';
            ctx.fillStyle = BLUE;
            ctx.globalAlpha = markerVis * 0.9;
            ctx.fillText('(', sx - CW, sy);
            ctx.fillText(')', sx + CW, sy);
            ctx.globalAlpha = markerVis * pulse;
            ctx.fillText('@', sx, sy);

            // Label, to the left of the marker, with a leader line
            const lx = Math.max(4, sx - 260);
            const ly = sy - 34;
            ctx.font = `10px ui-monospace, SFMono-Regular, Menlo, monospace`;
            ctx.globalAlpha = markerVis * 0.95; ctx.fillStyle = GREY;
            ctx.fillText('LIMA, PE', lx, ly);
            ctx.globalAlpha = markerVis * 0.6; ctx.fillStyle = DIM;
            ctx.fillText('LAT -12.0464°  LONG -77.0428°', lx, ly + 16);
            ctx.globalAlpha = markerVis * 0.6; ctx.fillStyle = BLUE;
            ctx.fillText(`UTC-5 · ${remoteRef.current}`, lx, ly + 32);
            ctx.globalAlpha = markerVis * 0.4;
            ctx.strokeStyle = DIM;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(lx + 200, sy - 4);
            ctx.lineTo(sx - CW * 1.5, sy + 6);
            ctx.stroke();
            ctx.globalAlpha = 1;
        };

        const tick = (now: number) => {
            raf = requestAnimationFrame(tick);
            if (now - last < 33) return;
            const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
            last = now;
            // Earth turns west to east, so the surface drifts left to right.
            if (revealStart >= 0) lon0 -= SPIN_DEG_PER_S * dt;
            if (lon0 < -180) lon0 += 360;
            if (revealStart >= 0 && reveal < 1) reveal = Math.min(1, (now - revealStart) / 1400);
            draw(now);
        };

        const start = () => {
            if (raf !== null || disposed) return;
            if (reduced) {
                draw(performance.now());
                return;
            }
            last = 0;
            raf = requestAnimationFrame(tick);
        };
        const stop = () => {
            if (raf !== null) cancelAnimationFrame(raf);
            raf = null;
        };

        startRevealRef.current = () => {
            if (!reduced && revealStart < 0) revealStart = performance.now();
        };

        let ro: ResizeObserver | null = null;
        let io: IntersectionObserver | null = null;

        import('../../data/globe-land').then(({ LAND_BITS, LAND_W, LAND_H }) => {
            if (disposed) return;
            const bin = atob(LAND_BITS);
            land = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) land[i] = bin.charCodeAt(i);
            landW = LAND_W;
            landH = LAND_H;
            layout();
            if (revealedRef.current) startRevealRef.current?.();
            draw(performance.now());
            ro = new ResizeObserver(() => {
                layout();
                draw(performance.now());
            });
            ro.observe(canvas);
            io = new IntersectionObserver(([e]) => (e.isIntersecting ? start() : stop()));
            io.observe(canvas);
        });

        return () => {
            disposed = true;
            stop();
            ro?.disconnect();
            io?.disconnect();
            startRevealRef.current = null;
        };
    }, []);

    return (
        <canvas
            ref={canvasRef}
            aria-label="ASCII globe turning, with a marker on Lima, Peru"
            role="img"
            className={`pointer-events-none ${className}`}
        />
    );
}
